      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
      continue;
    }

    const taskBranch = `feature/${featureId}-${taskId}`;

    try {
      await dispatchOneReview({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        implRepoRoot,
        implRepoUrl,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        workflowLocalPath,
        maxTurns,
        maxTokens,
        logSinkEnabled,
        implementationModel,
        workspaceId,
        githubToken,
        broker,
        callbackUrl,
        emit,
      });
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
    }
  }
}

