/**
 * Fix agent claim protocol.
 *
 * Claims a `change_requested` task for fix agent dispatch. Writes a `fix_started`
 * log entry and sets task status to `in_progress` using first-push-wins semantics.
 *
 * The fix agent uses the same `kind=impl` broker contract as the impl agent, so
 * `dispatchExecutorResult` handles fix results without modification.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface ClaimFixTaskOptions {
  workspaceRoot: string;
  taskId: string;
  featureId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  skipJitter?: boolean;
  skipGit?: boolean;
}

export type ClaimFixResult =
  | { won: true }
  | {
      won: false;
      reason:
        | "task_not_change_requested"
        | "already_claimed"
        | "push_rejected"
        | "branch_missing";
    };

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Attempt to atomically claim a `change_requested` task for a fix agent.
 *
 * On success the task YAML has status: in_progress and a `fix_started` log entry.
 * The management repo HEAD remains on the task branch with the claim commit pushed.
 *
 * First-push-wins: if the push is rejected, another orchestrator instance claimed first.
 */
export async function claimFixTask(opts: ClaimFixTaskOptions): Promise<ClaimFixResult> {
  const {
    workspaceRoot,
    taskId,
    featureId,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    skipJitter = false,
    skipGit = false,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const branch = taskBranchName(featureId, taskId);

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
    } catch {
      return { won: false, reason: "push_rejected" };
    }

    // Checkout the task branch (must already exist for a change_requested task)
    const lsResult = spawnSync(
      "git",
      ["-C", workspaceRoot, "ls-remote", "--exit-code", "origin", `refs/heads/${branch}`],
      { env, encoding: "utf-8" },
    );
    if (lsResult.status !== 0) {
      return { won: false, reason: "branch_missing" };
    }

    try {
      execSync(`git -C "${workspaceRoot}" checkout -B "${branch}" "origin/${branch}"`, { env, stdio: "pipe" });
    } catch {
      return { won: false, reason: "push_rejected" };
    }
  }

  // Read task; verify it is still change_requested
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch {
    return { won: false, reason: "push_rejected" };
  }

  if (task.status !== "change_requested") {
    return { won: false, reason: "task_not_change_requested" };
  }

  // Guard: skip if last log entry is fix_started — another instance claimed already
  const lastEntry = task.log[task.log.length - 1];
  if (lastEntry?.action === "fix_started") {
    return { won: false, reason: "already_claimed" };
  }

  // Pre-commit jitter to reduce collision rate
  if (!skipJitter) {
    await sleep(50 + Math.random() * 450);
  }

  const now = new Date().toISOString();
  task.status = "in_progress";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({
    action: "fix_started",
    by: gitAuthorEmail,
    at: now,
    note: "Fix agent claimed — status set to in_progress.",
  });

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch {
    return { won: false, reason: "push_rejected" };
  }

  if (skipGit) return { won: true };

  const relPath = taskYamlRelPath(featureId, taskId);
  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): fix_started — status in_progress"`,
      { env, stdio: "pipe" },
    );
  } catch {
    return { won: false, reason: "push_rejected" };
  }

  const ourSha = execSync(
    `git -C "${workspaceRoot}" rev-parse HEAD`,
    { env, stdio: "pipe", encoding: "utf-8" },
  ).trim();

  const pushResult = spawnSync(
    "git",
    ["-C", workspaceRoot, "push", "origin", branch],
    { env, encoding: "utf-8" },
  );

  if (pushResult.status !== 0) {
    // Compare SHA: if ours landed, we won despite the rejection
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin "${branch}"`, { env, stdio: "pipe" });
    } catch {
      return { won: false, reason: "push_rejected" };
    }

    const remoteHeadSha = execSync(
      `git -C "${workspaceRoot}" rev-parse "origin/${branch}"`,
      { env, stdio: "pipe", encoding: "utf-8" },
    ).trim();

    if (remoteHeadSha !== ourSha) {
      return { won: false, reason: "push_rejected" };
    }
  }

  return { won: true };
}

