/**
 * Reviewer agent claim protocol.
 *
 * Claims an `in_review` task for reviewer dispatch. Writes a `reviewer_started`
 * log entry but does NOT change the task status (stays `in_review`).
 * The task branch must already exist.
 *
 * First-push-wins: if the push is rejected, another orchestrator instance claimed first.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface ClaimReviewTaskOptions {
  workspaceRoot: string;
  taskId: string;
  featureId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /** Max number of reviewer cycles before refusing to dispatch (default: 3). */
  maxReviewCycles?: number;
  skipJitter?: boolean;
  skipGit?: boolean;
}

export type ClaimReviewResult =
  | { won: true }
  | {
      won: false;
      reason:
        | "task_not_in_review"
        | "already_claimed"
        | "cycle_limit_reached"
        | "push_rejected"
        | "branch_missing";
    };

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Attempt to atomically claim an `in_review` task for a reviewer agent.
 *
 * On success the task YAML has a `reviewer_started` log entry and the claim
 * commit is pushed. Task status remains `in_review`.
 *
 * Returns `cycle_limit_reached` when the number of `reviewer_started` log
 * entries equals or exceeds `maxReviewCycles` — the escalation handler should
 * be triggered instead.
 */
export async function claimReviewTask(opts: ClaimReviewTaskOptions): Promise<ClaimReviewResult> {
  const {
    workspaceRoot,
    taskId,
    featureId,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    maxReviewCycles = 3,
    skipJitter = false,
    skipGit = false,
  } = opts;

  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const branch = taskBranchName(featureId, taskId);

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
    } catch {
      return { won: false, reason: "push_rejected" };
    }

    // Branch must already exist for an in_review task
    const lsResult = spawnSync(
      "git",
      ["-C", workspaceRoot, "ls-remote", "--exit-code", "origin", `refs/heads/${branch}`],
      { env, encoding: "utf-8" },
    );
    if (lsResult.status !== 0) {
      return { won: false, reason: "branch_missing" };
    }

    try {
      execSync(`git -C "${workspaceRoot}" checkout -B "${branch}" "origin/${branch}"`, { env, stdio: "pipe" });
    } catch {
      return { won: false, reason: "push_rejected" };
    }
  }

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch {
    return { won: false, reason: "push_rejected" };
  }

  if (task.status !== "in_review") {
    return { won: false, reason: "task_not_in_review" };
  }

  // Guard: skip if last log entry is reviewer_started (another instance claimed)
  const lastEntry = task.log[task.log.length - 1];
  if (lastEntry?.action === "reviewer_started") {
    return { won: false, reason: "already_claimed" };
  }

  // Cycle limit: count reviewer_started entries
  const reviewerStartedCount = task.log.filter((e) => e.action === "reviewer_started").length;
  if (reviewerStartedCount >= maxReviewCycles) {
    return { won: false, reason: "cycle_limit_reached" };
  }

  if (!skipJitter) {
