    for (const { task, featureId, requiredSkills } of featureEntries) {
      // Criterion 1: status must be ready on main.
      // If the feature branch already exists, the live state may have advanced
      // (e.g. in_progress or in_review) — read it and skip if no longer ready.
      if (task.status !== "ready") continue;
      const branch = taskBranchName(featureId, task.id);
      const relPath = taskYamlRelPath(featureId, task.id);
      const branchTask = tryReadTaskFromBranch(workspaceRoot, branch, relPath);
      if (branchTask && branchTask.status !== "ready") continue;

      // Criterion 2: all depends_on must be done (within this feature)
      if (task.depends_on.some((dep) => !doneSet.has(dep))) continue;

      // Criterion 3 + 4: task.repo must be a repo in this workspace (which is watched)
      if (!reachableRepoIds.has(task.repo)) continue;

      // Criterion 5: all required skills must exist in the workflow repo or workspace-local .claude/skills/
      const missing = requiredSkills.filter(
        (slug) => !skillDirExists(workflowRoot, workspaceRoot, slug),
      );
      if (missing.length > 0) {
        emitSkippedMissingSkill({
          type: "task_skipped_missing_skill",
          taskId: task.id,
          featureId,
          missingSkills: missing,
        });
        continue;
      }

      eligible.push({ task, featureId });
    }
  }

  // ── 6. Deterministic ordering ───────────────────────────────────────────
  // Sort ascending by numeric task ID (T1 < T5 < T10).
  eligible.sort((a, b) => taskNumericId(a.task.id) - taskNumericId(b.task.id));

  return eligible;
}

