export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /**
   * Max number of max-turns retries before falling through to blocked.
   * Read from EXECUTOR_MAX_RETRIES env var by the caller; default 3.
   */
  maxTaskRetries?: number;
  emit: (event: Record<string, unknown>) => void;
}

/**
 * Reset a task to `ready` and append a `retried` log entry.
 * Used by the max-turns retry path in dispatchExecutorResult.
 * Non-throwing: returns an error string on failure.
 */
function applyMaxTurnsRetry(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  attemptNumber: number,
  originalBlockedReason: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
): string | undefined {
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const now = new Date().toISOString();

  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout failed: ${String(e)}`;
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  task.status = "ready";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({
    action: "retried",
    by: gitAuthorEmail,
    at: now,
    note: `Max-turns retry attempt ${attemptNumber}. Original blocked_reason: ${originalBlockedReason}`,
  });

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): max-turns retry ${attemptNumber} — status → ready"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return `git push failed: ${push.stderr}`;
  }

  return undefined;
}

