import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import type { Task, TaskLogEntry } from "../types/task.js";
import { mutateTaskYaml } from "./mutate-task-yaml.js";
import { appendLogEntry } from "./append-log.js";
import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /**
   * Max number of max-turns retries before falling through to blocked.
   * Read from EXECUTOR_MAX_RETRIES env var by the caller; default 3.
   */
  maxTaskRetries?: number;
  emit: (event: Record<string, unknown>) => void;
}

/**
 * Reset a task to `ready` and append a `retried` log entry.
 * Used by the max-turns retry path in dispatchExecutorResult.
 * Non-throwing: returns an error string on failure.
 */
function applyMaxTurnsRetry(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  attemptNumber: number,
  originalBlockedReason: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
): string | undefined {
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const now = new Date().toISOString();

  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout failed: ${String(e)}`;
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  task.status = "ready";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({
    action: "retried",
    by: gitAuthorEmail,
    at: now,
    note: `Max-turns retry attempt ${attemptNumber}. Original blocked_reason: ${originalBlockedReason}`,
  });

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): max-turns retry ${attemptNumber} — status → ready"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return `git push failed: ${push.stderr}`;
  }

  return undefined;
}

/**
 * Apply the side effects that correspond to an executor result.
 * Called by the orchestrator polling loop after adapter.run() returns.
 * Partially throwing: mutateTaskYaml failures are thrown so the reap loop
 * can nack the completion and retry. appendLogEntry failures are emitted but
 * swallowed — a missing log entry is non-fatal.
 */
export async function dispatchExecutorResult(
  opts: DispatchExecutorResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    maxTaskRetries = 3,
    emit,
  } = opts;

  // pr_url from result.json — set by executor when it opened a PR.
  // Present on any terminal_status when commits were pushed and a PR was opened.
  const prUrl = result.pr_url;

  if (result.terminal_status === "in_review") {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }

    const runCompletedEntry: Omit<TaskLogEntry, "at"> = {
      action: "run_completed",
      by: gitAuthorEmail,
      note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: runCompletedEntry,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  } else {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    // Max-turns retry: when the executor hit the turn limit, retry up to maxTaskRetries
    // times by resetting the task to `ready` before writing `blocked`.
    const blockedReason = result.blocked_reason ?? "";
    if (
      result.terminal_status === "blocked" &&
      blockedReason.startsWith("max_turns")
    ) {
      let retriedCount = 0;
      try {
        const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
        execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
        execSync(
          `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
          { env, stdio: "pipe" },
        );
        const task = parseYaml(readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8")) as Task;
        retriedCount = task.log.filter((e) => e.action === "retried").length;
      } catch {
        retriedCount = maxTaskRetries; // Cannot read count — fall through to blocked
      }

      if (retriedCount < maxTaskRetries) {
        const attemptNumber = retriedCount + 1;
        const retryErr = applyMaxTurnsRetry(
          workspaceRoot,
          featureId,
          taskId,
          taskBranch,
          attemptNumber,
          blockedReason,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
        );
        if (retryErr) {
          emit({ type: "max_turns_retry_failed", task_id: taskId, feature_id: featureId, details: retryErr });
          // Fall through to blocked write
        } else {
          emit({
            type: "max_turns_retried",
            task_id: taskId,
            feature_id: featureId,
            attempt: attemptNumber,
            max: maxTaskRetries,
          });
          return; // Task reset to ready; skip blocked write
        }
      } else {
        emit({
          type: "max_turns_retry_limit_reached",
          task_id: taskId,
          feature_id: featureId,
          retried_count: retriedCount,
          max: maxTaskRetries,
        });
      }
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) {
      emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });
      throw new Error(mutateErr);
    }

    const blockedEntry: Omit<TaskLogEntry, "at"> = {
      action: "blocked",
      by: gitAuthorEmail,
      note: blockedReason || "executor returned non-in_review status",
      ...(result.token_usage !== undefined && { token_usage: result.token_usage }),
      ...(result.cost_usd !== undefined && { cost_usd: result.cost_usd }),
    };

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: blockedEntry,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  }
}
DISPATCHEOF
