 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
 *
 * Max-turns retry: when the executor hits its turn limit (blocked_reason starts with
 * "max_turns"), the task is reset to `ready` up to maxTaskRetries times before
 * permanently blocking. Each retry appends a `retried` log entry.
 *
 * Revised D5: the executor owns impl-PR creation (via /pr-create skill).
 * The orchestrator no longer opens impl PRs — it only records the pr_url
 * reported by the executor in result.json.
 *
 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
 * verify the resulting task state without running the full bootstrap + poll loop.
 */

import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import type { Task, TaskLogEntry } from "../types/task.js";
import { mutateTaskYaml } from "./mutate-task-yaml.js";
import { appendLogEntry } from "./append-log.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /** How many max-turns retries are allowed before permanently blocking. Default: 3. */
  maxTaskRetries?: number;
  emit: (event: Record<string, unknown>) => void;
}

// ── Max-turns retry helper ────────────────────────────────────────────────────

interface ApplyMaxTurnsRetryOpts {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/**
 * Reset a task to `ready` for a max-turns retry.
 * Appends a `retried` log entry and commits to the management repo task branch.
 * Throws on git or file-system errors so the caller can nack the completion.
 */
function applyMaxTurnsRetry(opts: ApplyMaxTurnsRetryOpts): void {
  const { workspaceRoot, featureId, taskId, taskBranch, gitAuthorEmail, gitAuthorName, sshKeyPath } = opts;
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;

  const now = new Date().toISOString();
  task.status = "ready";
  task.blocked_reason = null;
  task.log = [
    ...(task.log ?? []),
    { action: "retried", by: gitAuthorEmail, at: now, note: "max_turns limit hit — resetting to ready for retry" },
  ];
  task.execution = {
    ...task.execution,
    last_updated_by: gitAuthorEmail,
    last_updated_at: now,
  };

  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  const gitEnv = buildGitEnv(sshKeyPath, gitAuthorEmail, gitAuthorName);
  const relPath = taskYamlRelPath(featureId, taskId);

  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env: gitEnv, stdio: "pipe" });
  execSync(
    `git -C "${workspaceRoot}" commit -m "chore(${taskId}): reset to ready — max_turns retry"`,
    { env: gitEnv, stdio: "pipe" },
  );
  execSync(`git -C "${workspaceRoot}" push origin "${taskBranch}"`, { env: gitEnv, stdio: "pipe" });
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Apply the side effects that correspond to an executor result.
 * Called by the orchestrator polling loop after adapter.run() returns.
 * Partially throwing: mutateTaskYaml failures are thrown so the reap loop
 * can nack the completion and retry. appendLogEntry failures are emitted but
 * swallowed — a missing log entry is non-fatal.
 */
export async function dispatchExecutorResult(
  opts: DispatchExecutorResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    maxTaskRetries = 3,
    emit,
  } = opts;

  // pr_url from result.json — set by executor when it opened a PR.
  // Present on any terminal_status when commits were pushed and a PR was opened.
  const prUrl = result.pr_url;

  // ── Max-turns retry intercept ─────────────────────────────────────────────
  if (
    result.terminal_status === "blocked" &&
    typeof result.blocked_reason === "string" &&
    result.blocked_reason.startsWith("max_turns")
  ) {
    const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
    const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
    const retriedCount = (task.log ?? []).filter((e) => e.action === "retried").length;

    if (retriedCount < maxTaskRetries) {
      emit({
        type: "max_turns_retry",
        task_id: taskId,
        feature_id: featureId,
        attempt: retriedCount + 1,
        max: maxTaskRetries,
      });
      applyMaxTurnsRetry({ workspaceRoot, featureId, taskId, taskBranch, gitAuthorEmail, gitAuthorName, sshKeyPath });
      return;
    }

    emit({
      type: "max_turns_retry_limit_reached",
      task_id: taskId,
      feature_id: featureId,
      retried_count: retriedCount,
    });
    // Fall through to blocked handling below.
  }

  if (result.terminal_status === "in_review") {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
