/**
 * Reviewer result dispatcher — skeleton.
 *
 * Routes the reviewer executor's `terminal_status` to the appropriate handler:
 *
 *   passed          → T5 Auto-Done Writer (implemented by T5)
 *   change_requested → mutate task YAML to change_requested + log review URL
 *   escalate        → T6 Escalation Handler (implemented by T6)
 *
 * T5 and T6 fill in their respective branches. This file provides the routing
 * skeleton so the reap loop can call a single entry-point for all review results.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task, TaskLogEntry } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

// ── Public types ──────────────────────────────────────────────────────────────

/** Terminal status values the reviewer executor may produce. */
export type ReviewTerminalStatus = "passed" | "change_requested" | "escalate";

export interface ReviewResult {
  terminal_status: ReviewTerminalStatus;
  /** GitHub review URL for the REQUEST_CHANGES review posted by the reviewer. */
  review_url?: string;
  /** Reviewer verdict notes. */
  notes?: string;
  /** Confidence score (0–1) the reviewer attached to its decision. */
  confidence?: number;
}

export interface DispatchReviewResultOpts {
  result: ReviewResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  githubToken: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Mutate the task YAML to `change_requested`, append a log entry recording the
 * review URL, commit, and push to the task branch.
 *
 * Non-throwing: returns an error string on failure.
 */
function applyChangeRequested(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  result: ReviewResult,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
): string | undefined {
  const branch = taskBranchName(featureId, taskId);
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const now = new Date().toISOString();

  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${branch}"`, { env, stdio: "pipe" });
    execSync(`git -C "${workspaceRoot}" checkout -- .`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${branch}" "origin/${branch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout failed: ${String(e)}`;
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  task.status = "change_requested";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;

  const entry: TaskLogEntry = {
    action: "change_requested",
    by: gitAuthorEmail,
    at: now,
    note: result.review_url
      ? `Reviewer posted REQUEST_CHANGES. Review URL: ${result.review_url}`
      : "Reviewer posted REQUEST_CHANGES.",
    ...(result.review_url ? { review_url: result.review_url } : {}),
    ...(result.notes ? { notes: result.notes } : {}),
  };
  task.log.push(entry);

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): status → change_requested"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", branch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return `git push failed: ${push.stderr}`;
  }

  return undefined;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Dispatch a reviewer result to the appropriate handler.
 *
 * - `passed`           → emits `review_passed` event (T5 Auto-Done Writer fills the rest)
 * - `change_requested` → mutates task to `change_requested`, emits `review_change_requested`
 * - `escalate`         → emits `review_escalate` event (T6 Escalation Handler fills the rest)
 *
 * Partially throwing: YAML mutation failures throw so the reap loop can nack and retry.
 * Event-only paths (passed, escalate) are non-throwing.
 */
export async function dispatchReviewResult(
  opts: DispatchReviewResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  switch (result.terminal_status) {
    case "passed":
      // T5 Auto-Done Writer: write done log entry + auto-ready cascade
      emit({
        type: "review_passed",
        task_id: taskId,
        feature_id: featureId,
        notes: result.notes,
        confidence: result.confidence,
      });
      break;

    case "change_requested": {
      const err = applyChangeRequested(
        workspaceRoot,
        featureId,
        taskId,
        result,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
      );
      if (err) {
        emit({ type: "review_change_requested_failed", task_id: taskId, feature_id: featureId, details: err });
        throw new Error(err);
      }
      emit({
        type: "review_change_requested",
        task_id: taskId,
        feature_id: featureId,
        review_url: result.review_url,
        notes: result.notes,
      });
      break;
    }

    case "escalate":
      // T6 Escalation Handler: Slack message + mutate task to blocked
      emit({
        type: "review_escalate",
        task_id: taskId,
        feature_id: featureId,
        notes: result.notes,
        confidence: result.confidence,
      });
      break;

    default: {
      const unknown = (result as ReviewResult).terminal_status;
      emit({ type: "review_unknown_terminal_status", task_id: taskId, feature_id: featureId, terminal_status: unknown });
    }
  }
}

