/**
 * Reviewer result dispatcher — skeleton.
 *
 * Routes the reviewer executor's terminal_status to the appropriate handler:
 *
 *   in_review               → passed: T5 Auto-Done Writer (implemented by T5)
 *   blocked/change_requested → mutate task YAML to change_requested + log review URL
 *   blocked/escalate        → T6 Escalation Handler (implemented by T6)
 *
 * The reviewer executor maps its verdict onto `ExecutorResult.terminal_status`:
 *   verdict "passed"          → terminal_status: "in_review"
 *   verdict "change_requested"→ terminal_status: "blocked", blocked_reason: "change_requested"
 *   verdict "escalate"        → terminal_status: "blocked", blocked_reason: "escalate"
 *
 * T5 and T6 fill in their respective branches. This file provides the routing
 * skeleton so the reap loop can call a single entry-point for all review results.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { ExecutorResult } from "@workflow/runtime-abi";
import type { Task, TaskLogEntry } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

// ── Public types ──────────────────────────────────────────────────────────────

export interface DispatchReviewResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Mutate the task YAML to `change_requested`, append a log entry recording
 * the review URL, commit, and push to the task branch.
 *
 * Non-throwing: returns an error string on failure.
 */
function applyChangeRequested(opts: {
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  result: ExecutorResult;
  gitAuthorEmail: string;
  gitAuthorName: string;
  sshKeyPath: string | undefined;
}): string | undefined {
  const { workspaceRoot, featureId, taskId, taskBranch, result, gitAuthorEmail, gitAuthorName, sshKeyPath } = opts;
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
  const now = new Date().toISOString();

  try {
    execSync(`git -C "${workspaceRoot}" fetch origin "${taskBranch}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" checkout -B "${taskBranch}" "origin/${taskBranch}"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git fetch/checkout failed: ${String(e)}`;
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return `failed to read task YAML: ${String(e)}`;
  }

  task.status = "change_requested";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;

  const reviewUrl = (result as Record<string, unknown>)["review_url"] as string | undefined;
  const entry: TaskLogEntry = {
    action: "change_requested",
    by: gitAuthorEmail,
    at: now,
    note: reviewUrl
      ? `Reviewer posted REQUEST_CHANGES. Review URL: ${reviewUrl}`
      : "Reviewer posted REQUEST_CHANGES.",
    ...(reviewUrl ? { review_url: reviewUrl } : {}),
    ...(result.blocked_suggestion ? { notes: result.blocked_suggestion } : {}),
  };
  task.log.push(entry);

  try {
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  } catch (e) {
    return `failed to write task YAML: ${String(e)}`;
  }

  try {
    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
    execSync(
      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): status → change_requested"`,
      { env, stdio: "pipe" },
    );
  } catch (e) {
    return `git add/commit failed: ${String(e)}`;
  }

  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    return `git push failed: ${push.stderr}`;
  }

  return undefined;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Dispatch a reviewer result to the appropriate handler.
 *
 * - terminal_status "in_review"                          → reviewer passed (T5 fills the rest)
 * - terminal_status "blocked" + blocked_reason "change_requested"
 *                                                        → mutates task to change_requested
 * - terminal_status "blocked" + blocked_reason "escalate" → T6 Escalation Handler
 * - any other blocked_reason                             → emits review_escalate as fallback
 *
 * Partially throwing: YAML mutation failures throw so the reap loop can nack and retry.
 * Event-only paths (passed, escalate) are non-throwing.
 */
export async function dispatchReviewResult(
  opts: DispatchReviewResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  // "passed" verdict: reviewer approved — T5 handles auto-done transition
  if (result.terminal_status === "in_review") {
    emit({
      type: "review_passed",
      task_id: taskId,
      feature_id: featureId,
    });
    return;
  }

  // "change_requested" verdict: reviewer requests changes
  if (
    result.terminal_status === "blocked" &&
    result.blocked_reason === "change_requested"
  ) {
    const err = applyChangeRequested({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (err) {
      emit({ type: "review_change_requested_failed", task_id: taskId, feature_id: featureId, details: err });
      throw new Error(err);
    }
    emit({
      type: "review_change_requested",
      task_id: taskId,
      feature_id: featureId,
    });
    return;
  }

  // "escalate" verdict or any other blocked reason — T6 handles escalation
  emit({
    type: "review_escalate",
    task_id: taskId,
    feature_id: featureId,
    blocked_reason: result.blocked_reason,
    blocked_suggestion: result.blocked_suggestion,
  });
}
