CLAIM_FIX = '''/**
 * Fix agent claim protocol.
 *
 * Claims a change_requested task for fix agent dispatch. Writes a fix_started
 * log entry and sets task status to in_progress using first-push-wins semantics.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface ClaimFixTaskOptions {
  workspaceRoot: string;
  taskId: string;
  featureId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  skipJitter?: boolean;
  skipGit?: boolean;
}

export type ClaimFixResult = { won: true } | { won: false; reason: string };

export async function claimFixTask(opts: ClaimFixTaskOptions): Promise<ClaimFixResult> {
  const {
    workspaceRoot,
    taskId,
    featureId,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    skipJitter = false,
    skipGit = false,
  } = opts;

  const branch = taskBranchName(featureId, taskId);
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  if (!skipJitter) {
    const jitter = Math.floor(Math.random() * 3000);
    await new Promise((r) => setTimeout(r, jitter));
  }

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin "${branch}"`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${workspaceRoot}" checkout -B "${branch}" "origin/${branch}"`,
        { env: gitEnv, stdio: "pipe" },
      );
    } catch (e) {
      return { won: false, reason: `git fetch/checkout failed: ${String(e)}` };
    }
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return { won: false, reason: `failed to read task YAML: ${String(e)}` };
  }

  if (task.status !== "change_requested") {
    return { won: false, reason: `task status is ${task.status}, expected change_requested` };
  }

  const now = new Date().toISOString();
  task.status = "in_progress";
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({ action: "fix_started", by: gitAuthorEmail, at: now });

  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${workspaceRoot}" commit -m "chore(${taskId}): claim fix — status to in_progress"`,
        { env: gitEnv, stdio: "pipe" },
      );
    } catch (e) {
      return { won: false, reason: `git add/commit failed: ${String(e)}` };
    }

    const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", branch], {
      env: gitEnv,
      encoding: "utf-8",
    });
    if (push.status !== 0) {
      return { won: false, reason: `git push rejected (lost claim race): ${push.stderr}` };
    }
  }

  return { won: true };
}
