CLAIM_REVIEW = '''/**
 * Reviewer agent claim protocol.
 *
 * Claims an in_review task for reviewer dispatch. Writes a reviewer_started
 * log entry; status stays in_review (the reviewer does not own the task).
 * Enforces a per-task cycle limit to prevent infinite review loops.
 */

import { execSync, spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import { taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "../paths.js";
import { buildGitEnv } from "../git-env.js";

export interface ClaimReviewTaskOptions {
  workspaceRoot: string;
  taskId: string;
  featureId: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  /** Max reviewer cycles before declaring a cycle limit. Default: 3. */
  maxReviewCycles?: number;
  skipJitter?: boolean;
  skipGit?: boolean;
}

export type ClaimReviewResult =
  | { outcome: "won" }
  | { outcome: "lost"; reason: string }
  | { outcome: "cycle_limit_reached" };

export async function claimReviewTask(opts: ClaimReviewTaskOptions): Promise<ClaimReviewResult> {
  const {
    workspaceRoot,
    taskId,
    featureId,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    maxReviewCycles = 3,
    skipJitter = false,
    skipGit = false,
  } = opts;

  const branch = taskBranchName(featureId, taskId);
  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const gitEnv = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  if (!skipJitter) {
    const jitter = Math.floor(Math.random() * 3000);
    await new Promise((r) => setTimeout(r, jitter));
  }

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" fetch origin "${branch}"`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${workspaceRoot}" checkout -B "${branch}" "origin/${branch}"`,
        { env: gitEnv, stdio: "pipe" },
      );
    } catch (e) {
      return { outcome: "lost", reason: `git fetch/checkout failed: ${String(e)}` };
    }
  }

  let task: Task;
  try {
    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  } catch (e) {
    return { outcome: "lost", reason: `failed to read task YAML: ${String(e)}` };
  }

  if (task.status !== "in_review") {
    return { outcome: "lost", reason: `task status is ${task.status}, expected in_review` };
  }

  const reviewerStartedCount = (task.log ?? []).filter((e) => e.action === "reviewer_started").length;
  if (reviewerStartedCount >= maxReviewCycles) {
    return { outcome: "cycle_limit_reached" };
  }

  const now = new Date().toISOString();
  task.execution.last_updated_by = gitAuthorEmail;
  task.execution.last_updated_at = now;
  task.log.push({ action: "reviewer_started", by: gitAuthorEmail, at: now });

  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  if (!skipGit) {
    try {
      execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env: gitEnv, stdio: "pipe" });
      execSync(
        `git -C "${workspaceRoot}" commit -m "chore(${taskId}): reviewer_started log entry"`,
        { env: gitEnv, stdio: "pipe" },
      );
    } catch (e) {
      return { outcome: "lost", reason: `git add/commit failed: ${String(e)}` };
    }

    const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", branch], {
      env: gitEnv,
      encoding: "utf-8",
    });
    if (push.status !== 0) {
      return { outcome: "lost", reason: `git push rejected (lost claim race): ${push.stderr}` };
    }
  }

  return { outcome: "won" };
}
